1	import AppKit
2	
3	/// What the timeline's action lane and the Clip tab's lane share (spec §11
4	/// CI-4): the ORDER actions are numbered in, the words a band's label is made
5	/// of, the zoom test, and the one painter both call — so a band on the
6	/// timeline and the same band in the inspector cannot disagree about its
7	/// number or its ink.
8	///
9	/// Drawn in a FLIPPED view: `minY` is the band's top. Everything here is
10	/// relative to the band it is handed; where the band sits is its caller's.
11	enum ActionBands {
12	    /// Time order — start, then id for two that share one (they cannot
13	    /// overlap, but a zero-length action can sit on another's start). An
14	    /// action's NUMBER is its index here plus one, everywhere.
15	    static func ordered(_ clip: ClipSnapshot) -> [ActionSnapshot] {
16	        clip.actions.sorted { ($0.start, $0.id) < ($1.start, $1.id) }
17	    }
18	
19	    /// Which properties an action changes — the end patch's keys, spelled
20	    /// the way the model spells them, sorted (what the old Actions table
21	    /// printed beside each curve); `speed` when the end names a rate (spec
22	    /// §11 SR-21 (d)).
23	    static func keys(of patch: ActionPatch) -> [String] {
24	        var keys: [String] = []
25	        if let video = patch.video { keys.append(contentsOf: video.dictionary.keys) }
26	        if let audio = patch.audio { keys.append(contentsOf: audio.dictionary.keys) }
27	        if let text = patch.text { keys.append(contentsOf: text.dictionary.keys) }
28	        if let graphic = patch.graphic { keys.append(contentsOf: graphic.props.keys) }
29	        if patch.speed != nil { keys.append("speed") }
30	        return keys.sorted()
31	    }
32	
33	    /// A screencast zoom's shape — `add_zoom_action` writes exactly `scale`,
34	    /// `x` and `y` and nothing else, so an end patch of those three keys is
35	    /// drawn with the zoom glyph whichever door wrote it. An end naming a rate
36	    /// is not a zoom (spec §11 SR-21 (d)).
37	    static func isZoom(_ action: ActionSnapshot) -> Bool {
38	        let end = action.end
39	        guard let video = end.video, end.audio?.isEmpty ?? true, end.text?.isEmpty ?? true,
40	              end.graphic?.props.isEmpty ?? true, end.speed == nil
41	        else { return false }
42	        return Set(video.dictionary.keys) == ["scale", "x", "y"]
43	    }
44	
45	    /// How much a band says, by track size: S bars only, M the number (and
46	    /// the zoom glyph and the selected band's curve), L the label too.
47	    enum Level {
48	        case bars, number, label
49	
50	        init(sizeIndex: Int) {
51	            switch sizeIndex {
52	            case ..<1: self = .bars
53	            case 1: self = .number
54	            default: self = .label
55	            }
56	        }
57	    }
58	
59	    /// The resize zone at each end of a band (spec §11 CI-11): its outer
60	    /// 5 pt, on a band wide enough to hold two of them and a body.
61	    static let grip: CGFloat = 5
62	
63	    /// Which end of `band` the x falls in the grip of, or nil for the body —
64	    /// always nil on a band 15 pt wide or less, which is all body.
65	    static func gripEdge(in band: CGRect, at x: CGFloat) -> TimelineEdge? {
66	        guard band.width > grip * 3 else { return nil }
67	        if x - band.minX <= grip { return .start }
68	        if band.maxX - x <= grip { return .end }
69	        return nil
70	    }
71	
72	    /// One band. Normal: the action ink at 34 % with 1 pt ends at 75 %;
73	    /// hovered, 62 % with solid ends. Selected: solid, its text in
74	    /// `DS.actionInk`, and — from M — the curve as a 1.25 pt black-45 % line
75	    /// from the bottom-left corner to the top-right, unless `curve` is nil
76	    /// (a Speed band under the rate line, `RateGraph.bandCurve`, spec §11
77	    /// SR-26). The number, the glyph and the label run from the LEADING
78	    /// edge, so the band's bottom-right corner holds fill only (the proof
79	    /// samples it there). Hovered, a band wide enough to resize draws its two
80	    /// 5 pt grips last — white 80 %, or black 45 % on the selected band — so
81	    /// an unhovered band never has them (CI-11).
82	    static func draw(
83	        band: CGRect, number: Int, label: String?, curve: Curve?, zoom: Bool, selected: Bool,
84	        hovered: Bool, level: Level
85	    ) {
86	        guard band.width > 0, band.height > 0 else { return }
87	        NSGraphicsContext.current?.saveGraphicsState()
88	        NSBezierPath(rect: band).addClip()
89	        if selected {
90	            DS.action.setFill()
91	            band.fill()
92	        } else {
93	            DS.action.withAlphaComponent(hovered ? 0.62 : 0.34).setFill()
94	            band.fill()
95	            DS.action.withAlphaComponent(hovered ? 1 : 0.75).setFill()
96	            NSRect(x: band.minX, y: band.minY, width: 1, height: band.height).fill()
97	            NSRect(x: band.maxX - 1, y: band.minY, width: 1, height: band.height).fill()
98	        }
99	        defer {
100	            if hovered, band.width > grip * 3 {
101	                (selected ? NSColor.black.withAlphaComponent(0.45)
102	                    : NSColor.white.withAlphaComponent(0.8)).setFill()
103	                NSRect(x: band.minX, y: band.minY, width: grip, height: band.height).fill()
104	                NSRect(x: band.maxX - grip, y: band.minY, width: grip, height: band.height).fill()
105	            }
106	            NSGraphicsContext.current?.restoreGraphicsState()
107	        }
108	        guard level != .bars else { return }
109	        if selected, let curve {
110	            let path = curvePath(curve, in: band)
111	            path.lineWidth = 1.25
112	            NSColor.black.withAlphaComponent(0.45).setStroke()
113	            path.stroke()
114	        }
115	        let ink = selected ? DS.actionInk : NSColor.white
116	        let numberFont = DS.mono(9, weight: .semibold)
117	        let text = "\(number)"
118	        let numberWidth = ceil(text.size(withAttributes: [.font: numberFont]).width)
119	        var x = band.minX + 3
120	        TimelineDraw.truncated(
121	            text, in: CGRect(x: x, y: band.minY, width: numberWidth + 5, height: band.height),
122	            font: numberFont, color: ink)
123	        x += numberWidth + 2
124	        if zoom {
125	            TimelineDraw.symbol(
126	                "plus.magnifyingglass", fallback: "+",
127	                in: CGRect(x: x, y: band.minY, width: 11, height: band.height), tint: ink)
128	            x += 11 + 2
129	        }
130	        if level == .label, let label, !label.isEmpty {
131	            x += 2
132	            let room = CGRect(
133	                x: x, y: band.minY, width: max(band.maxX - 3 - x, 0), height: band.height)
134	            TimelineDraw.truncated(
135	                label, in: room, font: DS.sans(10, weight: .semibold), color: ink)
136	        }
137	    }
138	
139	    /// The easing as a line across `rect`: progress along x, the eased value
140	    /// up the rect (the view is flipped, so "up" is toward `minY`). The
141	    /// selected band strokes it, and so does the lane's `CurveGlyphView`.
142	    static func curvePath(_ curve: Curve, in rect: CGRect) -> NSBezierPath {
143	        let path = NSBezierPath()
144	        let steps = 16
145	        for step in 0...steps {
146	            let t = CGFloat(step) / CGFloat(steps)
147	            let point = CGPoint(
148	                x: rect.minX + t * rect.width, y: rect.maxY - eased(curve, t) * rect.height)
149	            if step == 0 { path.move(to: point) } else { path.line(to: point) }
150	        }
151	        return path
152	    }
153	
154	    /// A glyph's easing, not the core's: the shape reads as the curve, and no
155	    /// frame is computed from it.
156	    private static func eased(_ curve: Curve, _ t: CGFloat) -> CGFloat {
157	        switch curve {
158	        case .linear: return t
159	        case .easeIn: return t * t
160	        case .easeOut: return 1 - (1 - t) * (1 - t)
161	        case .easeInOut: return t < 0.5 ? 2 * t * t : 1 - 2 * (1 - t) * (1 - t)
162	        }
163	    }
164	}
