3	/// What the Clip tab's lane draws of the clip itself, under its bands (spec
4	/// §11 CI-12): the transition overlap's hatch, the two audio fades and the
5	/// two motion wedges — each nil when the timeline would not draw it, by the
6	/// timeline's own gates. Pure geometry, so a probe can read it.
7	struct ActionLaneDecor: Equatable {
8	    var hatch: CGRect?
9	    var fadeIn: CGRect?
10	    var fadeOut: CGRect?
11	    var wedgeIn: CGRect?
12	    var wedgeOut: CGRect?
13	}
14	
15	extension ActionLaneView {
16	    /// `lane` is the whole clip, start to end; every width is a fraction of
17	    /// the clip's length, at least 2 pt and never wider than the lane.
18	    func decor(_ clip: ClipSnapshot, in lane: CGRect) -> ActionLaneDecor {
19	        var decor = ActionLaneDecor()
20	        guard clip.duration > 0, lane.width > 0, lane.height > 0 else { return decor }
21	        let snapshot = binding.snapshot
22	        func width(_ ticks: Ticks) -> CGFloat {
23	            min(max(lane.width * CGFloat(ticks) / CGFloat(clip.duration), 2), lane.width)
24	        }
25	        // `drawTransition`'s gate: a transition, over a predecessor that
26	        // still runs when this clip starts.
27	        if clip.transitionIn != nil,
28	           let previous = snapshot.clips(onTrack: clip.track).last(where: {
29	               $0.start < clip.start
30	           }),
31	           previous.end > clip.start
32	        {
33	            decor.hatch = CGRect(
34	                x: lane.minX, y: lane.minY, width: width(previous.end - clip.start),
35	                height: lane.height)
36	        }
37	        if InspectorTab.hasAudio(clip, in: snapshot) {
38	            let audio = clip.audioProps
39	            let tall = min(10, lane.height)
40	            if audio.fadeIn > 0 {
41	                decor.fadeIn = CGRect(
42	                    x: lane.minX, y: lane.maxY - tall, width: width(audio.fadeIn), height: tall)
43	            }
44	            if audio.fadeOut > 0 {
45	                let w = width(audio.fadeOut)
46	                decor.fadeOut = CGRect(
47	                    x: lane.maxX - w, y: lane.maxY - tall, width: w, height: tall)
48	            }
49	        }
50	        // `drawNameStrip`'s gate, and `drawMotionWedges`' length: the EDGE's.
51	        if InspectorTab.hasPixels(clip, in: snapshot), let motion = clip.videoProps.motion {
52	            let tall = min(8, lane.height)
53	            if let edge = motion.inEdge, edge.isActive {
54	                decor.wedgeIn = CGRect(
55	                    x: lane.minX, y: lane.minY, width: width(edge.duration), height: tall)
56	            }
57	            if let edge = motion.out, edge.isActive {
58	                let w = width(edge.duration)
59	                decor.wedgeOut = CGRect(x: lane.maxX - w, y: lane.minY, width: w, height: tall)
60	            }
61	        }
62	        return decor
63	    }
64	
65	    /// The decor, drawn in the well before the bands: the hatch (white 26 %,
66	    /// the timeline's 3 pt on a 7 pt perpendicular period) with a 1 pt
67	    /// white-40 % right edge; each fade a right triangle along the bottom,
68	    /// rising toward the clip's inside, at white 16 % (the handoff's shape);
69	    /// each wedge a triangle hanging from the top, deepest at the clip's
70	    /// edge, in `DS.textFaint`.
71	    func drawDecor(_ clip: ClipSnapshot, in lane: CGRect) {
72	        let decor = decor(clip, in: lane)
73	        NSGraphicsContext.current?.saveGraphicsState()
74	        NSBezierPath(rect: lane).addClip()
75	        if let hatch = decor.hatch {
76	            TimelineDraw.hatch(
77	                hatch, color: NSColor.white.withAlphaComponent(0.26),
78	                spacing: 7 * 2.0.squareRoot(), lineWidth: 3)
79	            NSColor.white.withAlphaComponent(0.4).setFill()
80	            NSRect(x: hatch.maxX - 1, y: hatch.minY, width: 1, height: hatch.height).fill()
81	        }
82	        NSColor.white.withAlphaComponent(0.16).setFill()
83	        if let fade = decor.fadeIn {
84	            triangle(fade.minX, fade.maxY, fade.maxX, fade.maxY, fade.maxX, fade.minY)
85	        }
86	        if let fade = decor.fadeOut {
87	            triangle(fade.maxX, fade.maxY, fade.minX, fade.maxY, fade.minX, fade.minY)
88	        }
89	        DS.textFaint.setFill()
90	        if let wedge = decor.wedgeIn {
91	            triangle(wedge.minX, wedge.minY, wedge.maxX, wedge.minY, wedge.minX, wedge.maxY)
92	        }
93	        if let wedge = decor.wedgeOut {
94	            triangle(wedge.maxX, wedge.minY, wedge.minX, wedge.minY, wedge.maxX, wedge.maxY)
95	        }
96	        NSGraphicsContext.current?.restoreGraphicsState()
97	    }
98	
99	    private func triangle(
100	        _ x0: CGFloat, _ y0: CGFloat, _ x1: CGFloat, _ y1: CGFloat, _ x2: CGFloat, _ y2: CGFloat
101	    ) {
102	        let path = NSBezierPath()
103	        path.move(to: CGPoint(x: x0, y: y0))
104	        path.line(to: CGPoint(x: x1, y: y1))
105	        path.line(to: CGPoint(x: x2, y: y2))
106	        path.close()
107	        path.fill()
108	    }
109	}
