pub(crate) fn profile_factors(clip: &Clip) -> Option<(f64, f64)> {
    SpeedMap::of(clip)?;
    let rates = std::iter::once(clip.speed).chain(clip.actions.iter().filter_map(end_speed));
    let (low, high) = rates.fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), r| {
        (lo.min(r), hi.max(r))
    });
    Some((SPEED_MIN / low, SPEED_MAX / high))
}

impl Project {
    /// Scales every action's span with the clip, so an action keeps the
    /// same clip-relative FRACTION when the clip's length changes (spec §6,
    /// `set_speed`).
    ///
    /// Rounding can leave two adjacent actions touching by a tick; that is
    /// harmless, because evaluation orders actions by `(start, id)` and is
    /// defined for overlaps — only `add_action` refuses to create one.
    pub(crate) fn rescale_actions(&self, actions: &mut [Action], old: Ticks, new: Ticks) {
        if old <= 0 || new <= 0 || old == new {
            return;
        }
        let frame = self.frame();
        let factor = new as f64 / old as f64;
        for action in actions.iter_mut() {
            let (start, duration) = self.scaled_span(action, factor);
            // Clamped so the action still fits the clip and still has a
            // positive duration, which `validate` requires.
            action.start = start.clamp(0, new.saturating_sub(frame).max(0));
            action.duration = duration
                .max(frame)
                .min(new.saturating_sub(action.start))
                .max(1);
        }
    }

    /// `action`'s start and duration × `factor`, each rounded then snapped
    /// to the grid. A product that is not finite keeps the old value. NOT
    /// clamped: `rescale_actions` clamps what it takes from here, and
    /// `scaled_profile` leaves a speed action where it lands (spec §11
    /// SR-19 (b)).
    pub(crate) fn scaled_span(&self, action: &Action, factor: f64) -> (Ticks, Ticks) {
        let scaled_start = (action.start as f64 * factor).round();
        let scaled_duration = (action.duration as f64 * factor).round();
        let start = if scaled_start.is_finite() {
            self.snapped(scaled_start as Ticks)
        } else {
            action.start
        };
        let duration = if scaled_duration.is_finite() {
            self.snapped(scaled_duration as Ticks)
        } else {
            action.duration
        };
        (start, duration)
    }

    /// `clip` with its whole rate profile × `factor`, `duration` long (spec
    /// §11 SR-19 (a), (b)): `speed` and every action's numeric `end.speed`,
    /// each product clamped to `SPEED_MIN`–`SPEED_MAX` (no rate is
    /// rewritten when `factor` is 1). Every SPEED action's span scales by
    /// `duration / clip.duration`, snapped and NOT clamped into the clip, so
    /// one running past the end still does and S∞′(t·D′/D) = S∞(t); every
    /// other action is rescaled and clamped as `rescale_actions` does. The
    /// duration is then held through S∞ with the speed actions as they stand
    /// (D4-3's `duration_resnapped`), as `trim_end` leaves them; when the
    /// hold shortens the clip, the other actions are re-clamped into what is
    /// left, as `resnap_clip_times`' second pass does (`resnap_actions`).
    pub(crate) fn scaled_profile(&self, clip: &Clip, factor: f64, duration: Ticks) -> Clip {
        let mut scaled = clip.clone();
        if factor != 1.0 {
            scaled.speed = (clip.speed * factor).clamp(SPEED_MIN, SPEED_MAX);
    /// (spec §11, W-3): a word stays on the speech it times. Its
    /// `graphic.in` advances by the move as `trim_start`'s does, and the
    /// predecessor's `length` is untouched (road map 10's G-9).
    ///
    /// Without `alone`, a linked partner whose start is this clip's and
    /// which has a hard-cut predecessor of its own is rolled to the same
    /// `to` after it (spec §11 AU-93, `carried_edge`); with it, the clip's
    /// cut moves alone.
    pub fn roll(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        let hard_cut = |partner: &Clip| {
            self.clips_on_track(partner.track)
                .iter()
                .any(|c| c.id != partner.id && clip_end(c) == partner.start)
        };
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start && hard_cut(partner),
            |project, id| project.roll_one(id, to),
        )
    }

    fn roll_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Some(previous) = self
            .clips_on_track(target.track)
            .into_iter()
            .find(|c| c.id != target.id && clip_end(c) == target.start)
            .cloned()
        else {
            return Ok(Outcome::Refused(format!(
                "no clip on track {} ends where clip {clip} begins ({}), so there is no cut \
                 to roll",
                target.track, target.start
            )));
        };

        let frame = self.frame();
        let mut earliest = previous.start.saturating_add(frame);
        let mut latest = clip_end(&target).saturating_sub(frame);
        if let Some(start) = self.earliest_start_on_grid(&target) {
            earliest = earliest.max(start.max(0));
        }
        if let Some(end) = self.latest_end_on_grid(&previous) {
            latest = latest.min(end);
        }
        // The two source bounds arrive on the grid (`source_window.rs`
        // snaps each inward, and this pair is where that rule came from),
        // but the one-frame bounds are measured from the clips' own starts,
        // which a hand-written document may put off it. So both are snapped
        // INWARD again — up at the bottom, down at the top — and the cut
        // lands on a frame that is still inside the source both clips have.
        let earliest = self.snapped_up(earliest);
        let latest = self.snapped_down(latest);
        if earliest > latest {
            return Ok(Outcome::Identity);
        }
        let to = self.snapped(to).clamp(earliest, latest);
        // A ramped target's front edge is held where it still fits its
        // media, as `trim_start`'s is (spec §11 SR-18 (c)).
        let to = self.front_edge_held(&target, to);
        if to == target.start {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, to.saturating_sub(target.start));
        moved.graphic = graphic_advanced(target.graphic.as_ref(), to.saturating_sub(target.start));
        moved.start = to;
        moved.duration = clip_end(&target).saturating_sub(to);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, to.saturating_sub(target.start));
        }

        let mut grown = previous.clone();
        grown.duration = to.saturating_sub(previous.start);

        // The clamps make this unreachable for the pair itself; it is here
        // because every placement op checks, and because a track that
        // already held something the rule dislikes should not have it made
        // worse by an edit that thought it was safe.
        if let Err(why) =
            self.check_overlap_rule(&[moved.clone(), grown.clone()], target.track, &[])
        {
            return Ok(Outcome::Refused(why));
        }

        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(target.id) {
            *slot = moved;
        }
    /// Nothing moves, so there is no overlap to check and no transition can
    /// be gained; the actions are clip-relative and stay exactly where they
    /// are.
    ///
    /// **A linked partner on an unlocked track slips with it**, by the
    /// smaller in magnitude of the two clamped amounts, so the sound stays
    /// on its picture (spec §11 AU-94).
    pub fn slip(&self, clip: u32, delta: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let delta = self.snapped(delta);
        let Some(own) = self.slip_amount(&target, delta)? else {
            return Ok(Outcome::Identity);
        };
        let partner = self
            .partner(clip)
            .filter(|p| self.track(p.track).is_some_and(|t| !t.locked))
            .cloned();
        let mut amount = own;
        if let Some(partner) = &partner {
            let theirs = self.slip_amount(partner, delta)?.unwrap_or(0);
            if theirs.abs() < amount.abs() {
                amount = theirs;
            }
        }
        if amount == 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in std::iter::once(clip).chain(partner.map(|p| p.id)) {
            if let Some(slot) = next.clip_mut(id) {
                slot.source = match &slot.source {
                    Source::Media {
                        media,
                        r#in,
                        reversed,
                    } => Source::Media {
                        media: *media,
                        r#in: r#in.saturating_add(amount),
                        reversed: *reversed,
                    },
                    Source::Still { media, at } => Source::Still {
                        media: *media,
                        at: at.saturating_add(amount),
                    },
                    other => other.clone(),
                };
            }
        }
        self.finish(next)
    }

//! The action ops — spec §6, table "Actions".
//!
//! An action is a span of CLIP time with an end patch: the clip's props
//! interpolate from whatever they are toward that patch across it (spec
//! §5.4). `actions.rs` evaluates them; this file is the four edits that put
//! one on a clip, retime it, change what it animates, and take it off
//! again.
//!
//! Split out of `edit_clip.rs` (which owns placement) because they are a
//! separate concern with one rule of their own — **actions on a clip may
//! not overlap**, and both `add_action` and `set_action` refuse rather than
//! repair, exactly as placement refuses rather than pushes. The lookups,
//! the frame snapping and [`Project::finish`] are `edit_clip.rs`'s
//! `pub(crate)` helpers, called and never restated.
//!
//! One asymmetry is deliberate and worth stating, and D1·2 moved where it
//! falls. An end patch is walked for keys and types like every other patch
//! ([`check_end_patch`], over `patch.rs`'s walk), so a misspelt key here is
//! refused by its path rather than stored and silently ignored; what stays
//! LENIENT is the VALUE, because the state a clip interpolates toward may
//! name something no stored group could hold, and because a half-written
//! animation must stay editable. The evaluator is the line of defence for
//! that — it clamps every value it produces (spec §5.4). The one exception
//! is a graphic prop's end (spec §11 G-34 (c)), checked against the op's
//! `schema`: nothing clamps a prop, and a curve between two in-range ends
//! stays in range. The forward
//! compatibility the old leniency was for lives in the FILE reader, which
//! keeps an `end` object exactly as it found it.
//!
//! It has exactly ONE refusal beyond "the patch must be an object", and it
//! is about a key that is not a value at all: `video.motion` (format
//! version 8) names a PRESET anchored to the clip's two ends, not a
//! quantity to ramp between two states, so an action cannot target it and
//! `set_action_end` says so by name. The refusal is a courtesy rather than
//! the enforcement — `evaluate_clip` restores the base motion over whatever
//! any end patch carries, which is what closes a hand-written file, a
//! pasted action and a project from another tool at once. A `graphic`
//! group in `patch` is `edit_action_graphic.rs`'s arm (spec §11 G-34); in
//! `off` it is an `Err`.

