/// The `x`, `y` that put the region's centre at the canvas centre at
/// `scale` — the module doc's `(x′, y′) = − s′ · R(θ) · (c + q_c)`.
///
/// `crop` reaches this only through `c`, the cropped rect's centre measured
/// from the uncropped one, which is the same expression
/// [`crate::nest::Frame::enter`] folds a nest's crop with.
pub(crate) fn zoom_offset(video: &VideoProps, region: &ZoomRegion, scale: f64) -> (f64, f64) {
    let crop = video.crop;
    let cx = (crop.l - crop.r) / 2.0 + region.x;
    let cy = (crop.t - crop.b) / 2.0 + region.y;
    let (x, y) = rotate(scale * cx, scale * cy, video.rotation);
    (-x, -y)
}

/// The size of a region with the canvas's aspect that `fit` solves to
/// exactly `scale` on a layer rotated `rotation` degrees (spec §11 CU-70):
/// `a·(W, H)` with `a = min(W / (W·k + H·m), H / (W·m + H·k)) / scale`, so
/// `zoom_scale`'s fit formula gives back `scale` (inside the legal range).
pub(crate) fn region_size(canvas: (f64, f64), scale: f64, rotation: f64) -> (f64, f64) {
    let (width, height) = canvas;
    let (sin, cos) = rotation.to_radians().sin_cos();
    let (k, m) = (cos.abs(), sin.abs());
    let a = (width / (width * k + height * m)).min(height / (width * m + height * k)) / scale;
    (a * width, a * height)
}

